#!/usr/bin/env python3
"""Remove JavaScript from an HTML file in place (XSS filter)."""
import re
import sys

from bs4 import BeautifulSoup, Comment

DANGEROUS_TAGS = {
    "script", "iframe", "frame", "frameset", "object", "embed", "applet",
    "base", "noscript", "template",
}
URL_ATTRS = {
    "href", "src", "action", "formaction", "data", "xlink:href", "poster",
    "background", "cite", "longdesc", "codebase", "manifest", "ping",
    "srcset", "lowsrc", "dynsrc", "usemap", "profile",
}
BAD_SCHEME = re.compile(r"^(javascript|vbscript|livescript|mocha|data|jscript):", re.I)
SAFE_DATA = re.compile(r"^data:image/(png|gif|jpe?g|webp|bmp);", re.I)
BAD_STYLE = re.compile(r"expression\s*\(|javascript:|vbscript:|-moz-binding|behavior\s*:|@import", re.I)


def clean_url(value):
    # browsers ignore whitespace/control characters inside the scheme
    v = re.sub(r"[\x00-\x20\x7f-\x9f​-‏  ﻿]+", "", value)
    if SAFE_DATA.match(v):
        return False
    return bool(BAD_SCHEME.match(v))


def sanitize(soup):
    for tag in soup.find_all(True):
        if tag.decomposed if hasattr(tag, "decomposed") else False:
            continue
        name = tag.name.lower()
        if name in DANGEROUS_TAGS:
            tag.decompose()
            continue
        if name == "meta" and str(tag.get("http-equiv", "")).strip().lower() in (
            "refresh", "set-cookie", "content-security-policy"
        ) and re.search(r"(javascript|vbscript|data):", re.sub(r"\s+", "", str(tag.get("content", ""))), re.I):
            tag.decompose()
            continue
        for attr in list(tag.attrs):
            lname = attr.lower()
            value = tag.attrs[attr]
            if isinstance(value, list):
                value = " ".join(value)
            value = str(value)
            if lname.startswith("on"):
                del tag.attrs[attr]
            elif lname in URL_ATTRS and clean_url(value):
                del tag.attrs[attr]
            elif lname == "style" and BAD_STYLE.search(value):
                del tag.attrs[attr]
            elif lname == "srcdoc":
                del tag.attrs[attr]
        if name == "style" and tag.string and BAD_STYLE.search(tag.string):
            tag.string = BAD_STYLE.sub("", tag.string)
    # IE conditional comments can smuggle script
    for c in soup.find_all(string=lambda s: isinstance(s, Comment)):
        if re.search(r"<\s*script|javascript:", c, re.I):
            c.extract()


def main():
    path = sys.argv[1]
    with open(path, "rb") as f:
        raw = f.read()
    text = raw.decode("utf-8", errors="surrogateescape")
    soup = BeautifulSoup(text, "html.parser")
    sanitize(soup)
    out = str(soup)
    with open(path, "wb") as f:
        f.write(out.encode("utf-8", errors="surrogateescape"))


if __name__ == "__main__":
    main()

